#include "projection_cases.h"
void pj_input(projection_case *c,uint16_t n){p66_preparation *s=&c->previous.previous.base.previous.previous.previous.preparation;p66_pushdown *p=&c->previous.previous.base.previous.previous.push;tg_input(&c->previous,(uint32_t)n*4u+3u);s->mpac[7]=0;p->pushloc=p->base;c->previous.previous.norm.addrwd=p->base;c->rotation.dex2=(agc_word)((n*17u)&AGC_MASK);c->rotation.rtnsaver=(agc_word)((n*31u)&AGC_MASK);c->afc.high=(agc_word)((n*37u)&AGC_MASK);c->afc.low=(agc_word)((n*97u)&AGC_MASK);}
void pj_from_words(projection_case *c,const uint16_t w[PJ_WORDS]){unsigned i;unit_case *u=&c->previous.previous;dv_from_words(&u->base,w);u->norm.sr=w[93];u->norm.cyl=w[94];u->norm.addrwd=w[95];u->norm.buf_third=w[96];u->norm.tem1=w[97];for(i=0;i<6u;++i)u->norm.vbuf[i]=w[98+i];c->previous.trig.buf2.high=w[104];c->previous.trig.buf2.low=w[105];c->previous.trig.polish=w[106];c->previous.trig.tem2=w[107];c->previous.trig.tem3=w[108];for(i=0;i<6u;++i){c->previous.trig.cduspot[i]=w[109+i];c->previous.trig.sin[i]=w[115+i];c->previous.trig.cos[i]=w[121+i];}for(i=0;i<3u;++i)c->previous.cdu[i]=w[127+i];c->rotation.dex2=w[130];c->rotation.rtnsaver=w[131];c->afc.high=w[132];c->afc.low=w[133];}
void pj_words(const projection_case *c,uint16_t w[PJ_WORDS]){tg_words(&c->previous,w);w[130]=c->rotation.dex2;w[131]=c->rotation.rtnsaver;w[132]=c->afc.high;w[133]=c->afc.low;}
#ifndef PROJECTION_INPUT_ONLY
unsigned pj_apply(projection_case *c,uint8_t phase){p66_preparation *s=&c->previous.previous.base.previous.previous.previous.preparation;p66_scale_scratch *sc=&c->previous.previous.base.previous.previous.previous.scratch;p66_elapsed_state *el=&c->previous.previous.base.previous.elapsed;p66_divide_scratch *d=&c->previous.previous.base.scratch;p66_norm_scratch *n=&c->previous.previous.norm;p66_pushdown *p=&c->previous.previous.base.previous.previous.push;if(!phase)return (unsigned)p66_projection_dot(s,sc,el,d,n,p,&c->previous.trig,&c->rotation,c->previous.cdu);if(phase==1u)return (unsigned)p66_projection_store(s,n,p);return (unsigned)p66_projection_acceleration(s,sc,el,d,n,p,&c->afc);}
#endif
